import styled from '@emotion/styled';
import { Heading } from 'components/UI';
import { theme } from 'theme';

export const StyledStrategicInnovationTitle = styled(Heading)({
  marginBottom: theme.spacing['6'],
});

export const StyledHeaderContainer = styled.div({
  fontWeight: 600,
  display: 'flex',
  justifyContent: 'center',
  padding: '12px',
  borderRadius: '16px 16px 0 0',
  borderBottom: '1px solid #14141429',
});

export const StyledStrategicInnovationContainer = styled.div({
  display: 'flex',
  gap: theme.spacing['2'],
  width: '100%',
  flexWrap: 'wrap',
});

export const StyledStrategicInnovationHeader = styled.span({
  fontSize: '20px !important',
  fontWeight: 600,
  lineHeight: '24px',
  color: theme.colors.txt.default,
  fontFamily: 'Barlow',
});

type StrategicInnovationVariant = 'default' | 'portfolio';

interface StyledStrategicInnovationItemProps {
  $variant?: StrategicInnovationVariant;
}

export const StyledStrategicInnovationItem = styled.div<StyledStrategicInnovationItemProps>(
  ({ $variant = 'default' }) => ({
    display: 'flex',
    flexDirection: 'column',
    borderRadius: '16px',
    border: '1px solid #14141429',
    flex: 1,
    minWidth: 0,
    maxWidth: '100%',
    overflow: 'hidden',
    ...($variant === 'portfolio' && {
      flex: 2,
    }),
  }),
);
